(5300161, 770353, 15711, '<td valign="top">Beautiful scene. Makes me think of orange sherbet.</td>', 'Beautiful scene. Makes me think of orange sherbet.', '2009-03-11 00:03:05.000000', NULL, 1),
(5300162, 771962, 84124, '<td valign="top">First one I''m voting on, and I may have to go outside and have a cigarette (and I don''t smoke).  Nice!</td>', 'First one I''m voting on, and I may have to go outside and have a cigarette (and I don''t smoke).  Nice!', '2009-03-11 00:03:13.000000', NULL, 1),
(5300167, 771173, 15711, '<td valign="top">Striking. The catch light in his eye - such a wise fellow.  Beautiful.</td>', 'Striking. The catch light in his eye - such a wise fellow.  Beautiful.', '2009-03-11 00:03:53.000000', NULL, 1),
(5300169, 772377, 77724, '<td valign="top">I like the theme here - nicely lit too</td>', 'I like the theme here - nicely lit too', '2009-03-11 00:04:15.000000', NULL, 1),
(5300173, 771321, 98339, '<td valign="top">A very lovely spot, I like the path that leads through the photo, but it seems to be overexposed to much... personally I like a really deep tone...this doesn''t mean it isn''t a great capture, it almost has a "negative" feel</td>', 'A very lovely spot, I like the path that leads through the photo, but it seems to be overexposed to much... personally I like a really deep tone...this doesn''t mean it isn''t a great capture, it almost has a "negative" feel', '2009-03-11 00:04:32.000000', NULL, 1),
(5300174, 771153, 84124, '<td valign="top">Hey, I recognize that fly!  Sure is nice to look at.  You and your bugs, absolutely incredible.</td>', 'Hey, I recognize that fly!  Sure is nice to look at.  You and your bugs, absolutely incredible.', '2009-03-11 00:04:38.000000', NULL, 1),
(5300176, 772511, 41370, '<td valign="top">Beautiful colors, sharp</td>', 'Beautiful colors, sharp', '2009-03-11 00:04:51.000000', NULL, 1),
(5300177, 772520, 48227, '<td valign="top">Love it!! 10</td>', 'Love it!! 10', '2009-03-11 00:04:53.000000', NULL, 1),
