(5301072, 771732, 76430, '<td valign="top">OK, you Icelanders will undoubtedly have the ribbons wrapped up.  Nice wide angle shot.  I love the trace of red in the sky.  Is that Quietude?</td>', 'OK, you Icelanders will undoubtedly have the ribbons wrapped up.  Nice wide angle shot.  I love the trace of red in the sky.  Is that Quietude?', '2009-03-11 01:03:52.000000', NULL, 1),
(5301073, 771984, 97225, '<td valign="top">This makes a stunning abstract. The detail and colour are beautiful.</td>', 'This makes a stunning abstract. The detail and colour are beautiful.', '2009-03-11 01:03:55.000000', NULL, 1),
(5301075, 771861, 31664, '<td valign="top">Doh! Great timing.</td>', 'Doh! Great timing.', '2009-03-11 01:03:58.000000', NULL, 1),
