(5303767, 770784, 44751, '<td valign="top">Nice rays of light.  Not quite enough in the image to really excite me but an pleasant shot.  Good luck: 6.</td>', 'Nice rays of light.  Not quite enough in the image to really excite me but an pleasant shot.  Good luck: 6.', '2009-03-11 06:32:37.000000', NULL, 1),
(5303768, 771339, 49109, '<td valign="top">nice diea, but the OOF portion at right side is rather distracting</td>', 'nice diea, but the OOF portion at right side is rather distracting', '2009-03-11 06:32:38.000000', NULL, 1),
(5303769, 772072, 102534, '<td valign="top">WOW WOW WOW. fantastic image. I''d give it 20 if I could</td>', 'WOW WOW WOW. fantastic image. I''d give it 20 if I could', '2009-03-11 06:32:52.000000', NULL, 1),
