(5305029, 770681, 56275, '<td valign="top">Wow! A lot of fish!! Underwater shots are tough.. wish it had a bit more color.</td>', 'Wow! A lot of fish!! Underwater shots are tough.. wish it had a bit more color.', '2009-03-11 08:52:29.000000', NULL, 1),
(5305030, 772007, 81530, '<td valign="top">Very nice hues.</td>', 'Very nice hues.', '2009-03-11 08:52:34.000000', NULL, 1),
