INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5306092, 771917, 15305, '<td valign="top">Amazing post processing, brings out the textures all over the shot.</td>', 'Amazing post processing, brings out the textures all over the shot.', '2009-03-11 10:06:12.000000', NULL, 1),
(5306094, 771954, 15305, '<td valign="top">Great capture!</td>', 'Great capture!', '2009-03-11 10:06:26.000000', NULL, 1),
(5306095, 771118, 65234, '<td valign="top">Reminds me of late nights coming home from the library in college for some reason.</td>', 'Reminds me of late nights coming home from the library in college for some reason.', '2009-03-11 10:06:30.000000', NULL, 1),
(5306096, 772011, 54228, '<td valign="top">I would wish for a tad more illumination on the flower. Nice shot.</td>', 'I would wish for a tad more illumination on the flower. Nice shot.', '2009-03-11 10:06:32.000000', NULL, 1),
(5306098, 772041, 43463, '<td valign="top">Love the sunset colors for they add such warmth and vibrancy to the scene captured. A vaquero/vaquera and his/her horse out for a stroll at the end of the day is the scene that unfolds before me. Love the pose of the horse - (I have to say it very much reminds me of a classic pose that they have for the Breyer horse models...yes, I had them as a child and now my eldest has her own collection). The silhouettes of the horse and rider are nice deep blacks that contrast wonderfully against the sunset sky. Going back to the pose of the horse and rider, the horse seems about to turn away to turn towards the direction of the sunset. I feel like I am there to see this horse and rider on the hill and then, they turn and ride down the other side - off into the sunset.</td>', 'Love the sunset colors for they add such warmth and vibrancy to the scene captured. A vaquero/vaquera and his/her horse out for a stroll at the end of the day is the scene that unfolds before me. Love the pose of the horse - (I have to say it very much reminds me of a classic pose that they have for the Breyer horse models...yes, I had them as a child and now my eldest has her own collection). The silhouettes of the horse and rider are nice deep blacks that contrast wonderfully against the sunset sky. Going back to the pose of the horse and rider, the horse seems about to turn away to turn towards the direction of the sunset. I feel like I am there to see this horse and rider on the hill and then, they turn and ride down the other side - off into the sunset.', '2009-03-11 10:06:39.000000', NULL, 1),
(5306099, 772239, 21714, '<td valign="top">Kudos to ya! <br/>Brilliant. 10.</td>', 'Kudos to ya! Brilliant. 10.', '2009-03-11 10:06:48.000000', NULL, 1),
(5306100, 772531, 88822, '<td valign="top">the background is a little distracting, the expression on her face is more of "i''m bored" in my opinion, and she is a little over exposed.</td>', 'the background is a little distracting, the expression on her face is more of "i''m bored" in my opinion, and she is a little over exposed.', '2009-03-11 10:06:51.000000', NULL, 1),
