INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5309609, 771151, 41802, '<td valign="top">Cool shot.  The lighting is awesome.</td>', 'Cool shot.  The lighting is awesome.', '2009-03-11 14:29:13.000000', NULL, 1),
(5309610, 772074, 81530, '<td valign="top">A little dark overall.</td>', 'A little dark overall.', '2009-03-11 14:29:16.000000', NULL, 1),
(5309611, 770289, 15711, '<td valign="top">I like the swirling movement of the tide around the rocks.  The subtle color palette is natural and not overdone.  Very pretty.</td>', 'I like the swirling movement of the tide around the rocks.  The subtle color palette is natural and not overdone.  Very pretty.', '2009-03-11 14:29:21.000000', NULL, 1),
(5309612, 772323, 55005, '<td valign="top">Beautiful portrait.  I am not too hot about the lamp/ball, as it illuminates all the wrinkles on the floor cover and gives a weird halo to her legs.  I also find the light on the her knee a bit hot.  I''d probbaly score it higher if it was just the face or a crop that did not include lower body.  Having said all that, this is still a great image. 6.</td>', 'Beautiful portrait.  I am not too hot about the lamp/ball, as it illuminates all the wrinkles on the floor cover and gives a weird halo to her legs.  I also find the light on the her knee a bit hot.  I''d probbaly score it higher if it was just the face or a crop that did not include lower body.  Having said all that, this is still a great image. 6.', '2009-03-11 14:29:34.000000', NULL, 1),
(5309613, 770409, 30049, '<td valign="top">Should''ve used a quarter!  Just kidding.  This made me smile.  Nice use of DOF and vanishing point.  Good luck in the challenge.</td>', 'Should''ve used a quarter!  Just kidding.  This made me smile.  Nice use of DOF and vanishing point.  Good luck in the challenge.', '2009-03-11 14:29:36.000000', NULL, 1),
(5309614, 770435, 15711, '<td valign="top">This is strikingly beautiful.  I am in awe.  Congrats on a fine entry. Coming back to re-comment. This is by far my fav of the challenge. 10</td>', 'This is strikingly beautiful.  I am in awe.  Congrats on a fine entry. Coming back to re-comment. This is by far my fav of the challenge. 10', '2009-03-11 14:29:41.000000', NULL, 1),
(5309615, 771461, 41802, '<td valign="top">Wow very nice high perspective.</td>', 'Wow very nice high perspective.', '2009-03-11 14:29:46.000000', NULL, 1),
(5309616, 771863, 30861, '<td valign="top">What a tribute! It would be great to see this actually win, on sentimental value alone, and it''s very nicely done, so it gets my first 10 :-)</td>', 'What a tribute! It would be great to see this actually win, on sentimental value alone, and it''s very nicely done, so it gets my first 10 :-)', '2009-03-11 14:29:47.000000', NULL, 1),
