INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5313674, 772548, 66515, '<td valign="top">A little oversaturated and oversharpened in my opinion. A good way to boost saturation naturally with good effect is selecting cloudy for your white balance. It will warm up the colors nicely without resulting in unnatural looking colors.</td>', 'A little oversaturated and oversharpened in my opinion. A good way to boost saturation naturally with good effect is selecting cloudy for your white balance. It will warm up the colors nicely without resulting in unnatural looking colors.', '2009-03-11 19:51:03.000000', NULL, 1),
