(5317966, 771998, 88718, '<td valign="top">Picture composition is good but the colours and saturation make it look artificial.</td>', 'Picture composition is good but the colours and saturation make it look artificial.', '2009-03-12 03:29:12.000000', NULL, 1),
(5317967, 771284, 94235, '<td valign="top">Motion, sharpness and the leader''s facial expression lean toward the making of a great photo. Wonderful capture.</td>', 'Motion, sharpness and the leader''s facial expression lean toward the making of a great photo. Wonderful capture.', '2009-03-12 03:30:24.000000', NULL, 1),
(5317968, 772154, 58452, '<td valign="top">With a LCD on the back!! Let her have the digital next time. Her style demands it! A striking model with lovely big eyes. Excellent.</td>', 'With a LCD on the back!! Let her have the digital next time. Her style demands it! A striking model with lovely big eyes. Excellent.', '2009-03-12 03:30:38.000000', NULL, 1),
(5317969, 772524, 88718, '<td valign="top">I like the expression and the hard light makes it a shot with questions unanswered. very good.</td>', 'I like the expression and the hard light makes it a shot with questions unanswered. very good.', '2009-03-12 03:30:45.000000', NULL, 1),
(5317970, 771889, 94235, '<td valign="top">Great tones. Looks like a wall hanging. Nice job!</td>', 'Great tones. Looks like a wall hanging. Nice job!', '2009-03-12 03:31:27.000000', NULL, 1),
