INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5318237, 771843, 47541, '<td valign="top">I''ve always liked masks (I regret not buying one when in Venice) ... nice shot, I feel a tighter crop on the face to accentuate the mask rather than allow us to glance over the persons shoulder</td>', 'I''ve always liked masks (I regret not buying one when in Venice) ... nice shot, I feel a tighter crop on the face to accentuate the mask rather than allow us to glance over the persons shoulder', '2009-03-12 04:34:50.000000', NULL, 1),
(5318238, 770450, 79141, '<td valign="top">nice image</td>', 'nice image', '2009-03-12 04:35:04.000000', NULL, 1),
(5318239, 771040, 98162, '<td valign="top">You should have stepped a bit to the left - so that the tree is not sort of emerging from her head. And waited till the pedestrian in the background disappeared. That would have made a much stronger image.</td>', 'You should have stepped a bit to the left - so that the tree is not sort of emerging from her head. And waited till the pedestrian in the background disappeared. That would have made a much stronger image.', '2009-03-12 04:35:09.000000', NULL, 1),
(5318240, 770986, 49109, '<td valign="top">beautiful, calm scenery, well exposed. had cropped off some of the dark foreground, though</td>', 'beautiful, calm scenery, well exposed. had cropped off some of the dark foreground, though', '2009-03-12 04:35:10.000000', NULL, 1),
(5318241, 772407, 47541, '<td valign="top">Oh, we see this in every city don''t we?  Tourists, we are all one sometimes.  Nice humorous capture</td>', 'Oh, we see this in every city don''t we?  Tourists, we are all one sometimes.  Nice humorous capture', '2009-03-12 04:35:27.000000', NULL, 1),
