INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5319520, 771712, 100064, '<td valign="top">Very darling and good lighting.</td>', 'Very darling and good lighting.', '2009-03-12 08:48:26.000000', NULL, 1),
(5319521, 770239, 47294, '<td valign="top">WOW, what a photo and what a title.  Beautiful capture, just excellent. 10 from me. Best of luck.</td>', 'WOW, what a photo and what a title.  Beautiful capture, just excellent. 10 from me. Best of luck.', '2009-03-12 08:48:36.000000', NULL, 1),
(5319522, 771444, 100064, '<td valign="top">Im not liking the colors. Looks very unnatural but I do like the subject.</td>', 'Im not liking the colors. Looks very unnatural but I do like the subject.', '2009-03-12 08:48:49.000000', NULL, 1),
(5319523, 772178, 43463, '<td valign="top">Voted earlier coming back now to leave comments. Holy...cow...I - am - <b>really</b>- glad to be sitting here and observing this as a picture (fear of heights). Though I imagine it must have be really breathtaking to observe in real time. Tis certainly cool to be above the cloud cover - I have experienced that once with driving into a cloud cover on the Blue Ridge Parkway in NC (an experience but one I do not readily seek to have again:-) ). O.K. back to the photo, I like how the composition has the road curving - those leading lines direct us to travel around the bend as we look upon the photo. But we also take a quick glance at what lies beyond with the billowy white clouds and the sky blue horizon. One also looks that there is no guardrail and tries not to think of how high up one is and how bad the fall would be....The unobstructed view of the wide open sky is that we feel we are above the heavens even though we are still rooted to the ground plane. Colors and details are wonderfully crisp.</td>', 'Voted earlier coming back now to leave comments. Holy...cow...I - am - really- glad to be sitting here and observing this as a picture (fear of heights). Though I imagine it must have be really breathtaking to observe in real time. Tis certainly cool to be above the cloud cover - I have experienced that once with driving into a cloud cover on the Blue Ridge Parkway in NC (an experience but one I do not readily seek to have again:-) ). O.K. back to the photo, I like how the composition has the road curving - those leading lines direct us to travel around the bend as we look upon the photo. But we also take a quick glance at what lies beyond with the billowy white clouds and the sky blue horizon. One also looks that there is no guardrail and tries not to think of how high up one is and how bad the fall would be....The unobstructed view of the wide open sky is that we feel we are above the heavens even though we are still rooted to the ground plane. Colors and details are wonderfully crisp.', '2009-03-12 08:49:06.000000', NULL, 1),
(5319524, 770336, 100064, '<td valign="top">I like the detail and focus on the horse and rider. The background being low light and misty makes it work nicely together.</td>', 'I like the detail and focus on the horse and rider. The background being low light and misty makes it work nicely together.', '2009-03-12 08:49:22.000000', NULL, 1),
(5319526, 771345, 100064, '<td valign="top">Very sweet and good lighting.</td>', 'Very sweet and good lighting.', '2009-03-12 08:49:33.000000', NULL, 1),
(5319527, 772623, 81530, '<td valign="top">Good use of selective desaturation.</td>', 'Good use of selective desaturation.', '2009-03-12 08:50:09.000000', NULL, 1),
(5319529, 770241, 100064, '<td valign="top">Wow. Great perspective.  Could have used a bit more punch in editing but I love the subject matter!</td>', 'Wow. Great perspective.  Could have used a bit more punch in editing but I love the subject matter!', '2009-03-12 08:50:17.000000', NULL, 1),
(5319530, 771402, 81530, '<td valign="top">He he. He is trying hard to hold his breath. Cute.</td>', 'He he. He is trying hard to hold his breath. Cute.', '2009-03-12 08:50:29.000000', NULL, 1),
