(5325944, 771733, 79141, '<td valign="top">not very interesting sorry</td>', 'not very interesting sorry', '2009-03-12 17:07:15.000000', NULL, 1),
(5325945, 772710, 100393, '<td valign="top">Great, honest portrait. The lack of gimmickry is noted and appreciated.</td>', 'Great, honest portrait. The lack of gimmickry is noted and appreciated.', '2009-03-12 17:07:23.000000', NULL, 1),
(5325946, 772561, 2612, '<td valign="top">I love the fact that you went for the subdued light and saturated colors of a rainy day vs the standard dramatic landscape with the contrast and color jacked way up. The golden leaves absolutely glow.</td>', 'I love the fact that you went for the subdued light and saturated colors of a rainy day vs the standard dramatic landscape with the contrast and color jacked way up. The golden leaves absolutely glow.', '2009-03-12 17:07:34.000000', NULL, 1),
(5325947, 771026, 73942, '<td valign="top">nice stairwell find, looks like a snail</td>', 'nice stairwell find, looks like a snail', '2009-03-12 17:07:35.000000', NULL, 1),
