(5326583, 770818, 73942, '<td valign="top">beautiful sky, nice lines in the sand and water</td>', 'beautiful sky, nice lines in the sand and water', '2009-03-12 18:06:28.000000', NULL, 1),
(5326585, 772272, 96751, '<td valign="top">Are you the puzzle man?  If so, you really like getting your hands dirty :-)  Very intriguing shot.  Makes me want to stop and look at what is drawn on it.  The composition is nice with the negative space, as is the hand position, but I would have liked a little more light on the palm to achieve the level of contrast on the base on the thumb.</td>', 'Are you the puzzle man?  If so, you really like getting your hands dirty :-)  Very intriguing shot.  Makes me want to stop and look at what is drawn on it.  The composition is nice with the negative space, as is the hand position, but I would have liked a little more light on the palm to achieve the level of contrast on the base on the thumb.', '2009-03-12 18:06:34.000000', NULL, 1),
(5326586, 772611, 65319, '<td valign="top">Hahahaha...thank you for this laugh!  7</td>', 'Hahahaha...thank you for this laugh!  7', '2009-03-12 18:06:50.000000', NULL, 1),
(5326587, 770595, 104378, '<td valign="top">more sky or more water, rule of thirds and this would have been VERY high up in my book.  4</td>', 'more sky or more water, rule of thirds and this would have been VERY high up in my book.  4', '2009-03-12 18:06:50.000000', NULL, 1),
