INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5328864, 772391, 10275, '<td valign="top">This is neat abstract image, but it is quite busy and due to it''s low contrast feeling, there really isn''t any focal point to rest your eyes on. The spiral staircase could be used as a diagonal to lead you into the image, maybe make it more prominant part of the image. Also, needs perspective correction (the walls are wonky).</td>', 'This is neat abstract image, but it is quite busy and due to it''s low contrast feeling, there really isn''t any focal point to rest your eyes on. The spiral staircase could be used as a diagonal to lead you into the image, maybe make it more prominant part of the image. Also, needs perspective correction (the walls are wonky).', '2009-03-12 21:19:35.000000', NULL, 1),
(5328865, 770247, 73942, '<td valign="top">great sky and leading lines, well done</td>', 'great sky and leading lines, well done', '2009-03-12 21:19:36.000000', NULL, 1),
