(5330062, 771813, 77724, '<td valign="top">contract seem harsh at first glance, but as I look more I find it really works.</td>', 'contract seem harsh at first glance, but as I look more I find it really works.', '2009-03-12 23:04:18.000000', NULL, 1),
(5330064, 770831, 96751, '<td valign="top">The contrail really adds such an interesting detail.</td>', 'The contrail really adds such an interesting detail.', '2009-03-12 23:04:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5330065, 771025, 37845, '<td valign="top">This shot reminds me of the movie "Ray". Great contrast... i like how you isolated your subject.</td>', 'This shot reminds me of the movie "Ray". Great contrast... i like how you isolated your subject.', '2009-03-12 23:04:52.000000', NULL, 1),
(5330066, 771729, 54228, '<td valign="top">Great lighting on these!</td>', 'Great lighting on these!', '2009-03-12 23:04:56.000000', NULL, 1),
(5330068, 772387, 37845, '<td valign="top">Really cool effect with the paper.</td>', 'Really cool effect with the paper.', '2009-03-12 23:05:13.000000', NULL, 1),
(5330070, 770882, 96751, '<td valign="top">Very sweet shot.  I love the enthusiasm in the child''s body language, and the blue-green tones of the water beyond the circle window.  The sun beams really create a sense of depth.</td>', 'Very sweet shot.  I love the enthusiasm in the child''s body language, and the blue-green tones of the water beyond the circle window.  The sun beams really create a sense of depth.', '2009-03-12 23:05:29.000000', NULL, 1),
(5330072, 772099, 2615, '<td valign="top">Beautiful portrait, great lighting.</td>', 'Beautiful portrait, great lighting.', '2009-03-12 23:05:42.000000', NULL, 1),
(5330073, 772626, 54228, '<td valign="top">Glad to see they''re still happy.</td>', 'Glad to see they''re still happy.', '2009-03-12 23:05:53.000000', NULL, 1),
(5330074, 771210, 96751, '<td valign="top">There''s a great story in this shot, mysterious and sad.</td>', 'There''s a great story in this shot, mysterious and sad.', '2009-03-12 23:05:58.000000', NULL, 1),
(5330076, 772058, 96751, '<td valign="top">The backlighting on the couple really makes them stand out in this street scene.</td>', 'The backlighting on the couple really makes them stand out in this street scene.', '2009-03-12 23:06:17.000000', NULL, 1),
(5330077, 772368, 18197, '<td valign="top">Water droplets add nicely to this image.</td>', 'Water droplets add nicely to this image.', '2009-03-12 23:06:19.000000', NULL, 1),
(5330079, 772090, 28742, '<td valign="top">Holy WOW! Never seen one of them before and this is a spectacular shot!</td>', 'Holy WOW! Never seen one of them before and this is a spectacular shot!', '2009-03-12 23:06:31.000000', NULL, 1),
(5330080, 772105, 69684, '<td valign="top">View and colors are great. I like the trees on both sides.</td>', 'View and colors are great. I like the trees on both sides.', '2009-03-12 23:06:35.000000', NULL, 1),
(5330081, 771043, 77724, '<td valign="top">Excellent composrition.  I liked to build model ships as a kid - this brings back many fond memories.</td>', 'Excellent composrition.  I liked to build model ships as a kid - this brings back many fond memories.', '2009-03-12 23:06:54.000000', NULL, 1),
(5330082, 772011, 71244, '<td valign="top">a perfect technical image.</td>', 'a perfect technical image.', '2009-03-12 23:07:18.000000', NULL, 1),
(5330083, 771720, 96751, '<td valign="top">Nice lines, love the scattered white shapes of the swans on the dark water.</td>', 'Nice lines, love the scattered white shapes of the swans on the dark water.', '2009-03-12 23:07:34.000000', NULL, 1),
(5330085, 771917, 18197, '<td valign="top">I think you''ve gone too far with the HDR effect. But having said that, I like absolutely everything else about your photo ... the composition, the detail, the colors, the focus and find it a pleasing image.</td>', 'I think you''ve gone too far with the HDR effect. But having said that, I like absolutely everything else about your photo ... the composition, the detail, the colors, the focus and find it a pleasing image.', '2009-03-12 23:07:51.000000', NULL, 1),
(5330086, 772302, 2615, '<td valign="top">I like the perspective but the lighting is a bit dark.</td>', 'I like the perspective but the lighting is a bit dark.', '2009-03-12 23:07:53.000000', NULL, 1),
(5330087, 770231, 43463, '<td valign="top">Voted earlier coming back to comment now. I love the lighting here - whenever there is mist with sunshine it really can transform the scene into something mystical and magical. The woods are transformed into a magical place with some nice sun rays playing through the mist. These woods breathe even more magic with the appearance of three deer that seem to appear from out of the mist. Love how you composed this to have the large tree in the far left and it''s branches act as a frame for this composition. It is like a curtain being drawn aside so that we can see this woodland trio. This is breathe taking to see but I bet it was even moreso to experience. Thank you for sharing this wonderful capture.</td>', 'Voted earlier coming back to comment now. I love the lighting here - whenever there is mist with sunshine it really can transform the scene into something mystical and magical. The woods are transformed into a magical place with some nice sun rays playing through the mist. These woods breathe even more magic with the appearance of three deer that seem to appear from out of the mist. Love how you composed this to have the large tree in the far left and it''s branches act as a frame for this composition. It is like a curtain being drawn aside so that we can see this woodland trio. This is breathe taking to see but I bet it was even moreso to experience. Thank you for sharing this wonderful capture.', '2009-03-12 23:07:56.000000', NULL, 1),
(5330088, 771934, 42495, '<td valign="top">I like the single tree and the golden sky; comp works well also.  However, it seems as if those really dark clouds all calling for attention, pulling my eye from the tree.</td>', 'I like the single tree and the golden sky; comp works well also.  However, it seems as if those really dark clouds all calling for attention, pulling my eye from the tree.', '2009-03-12 23:07:58.000000', NULL, 1),
(5330090, 772383, 54228, '<td valign="top">The harsh lighting and dominant blacks speak of a very dark future to me here... Also, the image does appear a little soft.</td>', 'The harsh lighting and dominant blacks speak of a very dark future to me here... Also, the image does appear a little soft.', '2009-03-12 23:08:04.000000', NULL, 1),
(5330091, 772565, 2615, '<td valign="top">Nice!</td>', 'Nice!', '2009-03-12 23:08:06.000000', NULL, 1),
(5330093, 772585, 96751, '<td valign="top">Looks like an entry from the Ansel challenge :-)  Very nice, a little dark along the bottom.</td>', 'Looks like an entry from the Ansel challenge :-)  Very nice, a little dark along the bottom.', '2009-03-12 23:08:27.000000', NULL, 1),
(5330094, 771218, 18197, '<td valign="top">Lovely image, among the best I''ve seen so far. Congratulations!</td>', 'Lovely image, among the best I''ve seen so far. Congratulations!', '2009-03-12 23:08:29.000000', NULL, 1),
(5330095, 770570, 2615, '<td valign="top">Great composition. I wish there was a little more color in the sky.</td>', 'Great composition. I wish there was a little more color in the sky.', '2009-03-12 23:08:42.000000', NULL, 1),
(5330097, 771028, 54228, '<td valign="top">I would like another stop and a half or so of exposure here to get that background blown a little and more detail in the dog.</td>', 'I would like another stop and a half or so of exposure here to get that background blown a little and more detail in the dog.', '2009-03-12 23:08:45.000000', NULL, 1),
(5330099, 771157, 69684, '<td valign="top">Wonderful view. Nice match of the colors of the pole and the bird.</td>', 'Wonderful view. Nice match of the colors of the pole and the bird.', '2009-03-12 23:08:58.000000', NULL, 1),
(5330100, 771435, 2615, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-03-12 23:09:04.000000', NULL, 1),
(5330101, 772471, 18197, '<td valign="top">Without the kids this would be yet another Louvre image. Great choice to include them!</td>', 'Without the kids this would be yet another Louvre image. Great choice to include them!', '2009-03-12 23:09:08.000000', NULL, 1),
(5330103, 771988, 54228, '<td valign="top">Feels very underexposed to me. The colours are nice, but the ring of black trees isn''t working for me.</td>', 'Feels very underexposed to me. The colours are nice, but the ring of black trees isn''t working for me.', '2009-03-12 23:09:18.000000', NULL, 1),
(5330106, 772607, 96751, '<td valign="top">The tree "hallway" is beautiful.  Incredible ground color; works well with the soft color in the trees, horse and rider.  The blue parka is kind of distracting, but the scene between the man and the rider is intimate.</td>', 'The tree "hallway" is beautiful.  Incredible ground color; works well with the soft color in the trees, horse and rider.  The blue parka is kind of distracting, but the scene between the man and the rider is intimate.', '2009-03-12 23:09:44.000000', NULL, 1),
(5330107, 772357, 18197, '<td valign="top">Very nice image. Good workmanlike technicals and a pleasant composition and color pallet.</td>', 'Very nice image. Good workmanlike technicals and a pleasant composition and color pallet.', '2009-03-12 23:09:49.000000', NULL, 1),
(5330108, 770839, 69684, '<td valign="top">Impressive waves! It''s almost like a dance.</td>', 'Impressive waves! It''s almost like a dance.', '2009-03-12 23:10:07.000000', NULL, 1),
(5330109, 771190, 96751, '<td valign="top">Orchids are so amazing.  I don''t know if I''ve seen one with a puffy part like that.</td>', 'Orchids are so amazing.  I don''t know if I''ve seen one with a puffy part like that.', '2009-03-12 23:10:11.000000', NULL, 1),
(5330110, 771373, 54228, '<td valign="top">Great idea to rotate what would have been a pretty standard reflection shot. The added interest was worth it!</td>', 'Great idea to rotate what would have been a pretty standard reflection shot. The added interest was worth it!', '2009-03-12 23:10:41.000000', NULL, 1),
(5330111, 772721, 2615, '<td valign="top">Pretty, but I think placing the horizon higher or lower might make the composition more interesting.</td>', 'Pretty, but I think placing the horizon higher or lower might make the composition more interesting.', '2009-03-12 23:10:44.000000', NULL, 1),
(5330112, 772409, 96751, '<td valign="top">The trees look like lace against the sky, great detail.  The sunset colors are very brilliant, but the shape of the cloud shadow on the water is really surprising.</td>', 'The trees look like lace against the sky, great detail.  The sunset colors are very brilliant, but the shape of the cloud shadow on the water is really surprising.', '2009-03-12 23:10:48.000000', NULL, 1),
(5330114, 771657, 18197, '<td valign="top">Okay, you convinced me. I don''t want to live in Bodie. I would actually like to see more of the scene, but the panorama format makes it hard.</td>', 'Okay, you convinced me. I don''t want to live in Bodie. I would actually like to see more of the scene, but the panorama format makes it hard.', '2009-03-12 23:10:57.000000', NULL, 1),
(5330116, 772105, 43667, '<td valign="top">I like the lone cypress in the shot.</td>', 'I like the lone cypress in the shot.', '2009-03-12 23:11:06.000000', NULL, 1),
(5330117, 770996, 96751, '<td valign="top">A memorable view.  Brings back memories of my Inca Trail hike to Machu Picchu.</td>', 'A memorable view.  Brings back memories of my Inca Trail hike to Machu Picchu.', '2009-03-12 23:11:23.000000', NULL, 1),
(5330118, 772175, 18197, '<td valign="top">Made me smile! This is among the challenge''s best.</td>', 'Made me smile! This is among the challenge''s best.', '2009-03-12 23:11:26.000000', NULL, 1),
(5330119, 771971, 54228, '<td valign="top">This is stunning! I love the focus, the depth of field, and the colour combination. Wonderful work.</td>', 'This is stunning! I love the focus, the depth of field, and the colour combination. Wonderful work.', '2009-03-12 23:11:44.000000', NULL, 1),
(5330120, 772709, 96751, '<td valign="top">This is very intriguing.  I want to know what she''s looking at.  The metalic tones really add oomph to this quirky shot.</td>', 'This is very intriguing.  I want to know what she''s looking at.  The metalic tones really add oomph to this quirky shot.', '2009-03-12 23:12:06.000000', NULL, 1),
(5330121, 771883, 54228, '<td valign="top">Fun indeed.</td>', 'Fun indeed.', '2009-03-12 23:12:07.000000', NULL, 1),
(5330122, 770859, 54228, '<td valign="top">Very nice colours and processing.</td>', 'Very nice colours and processing.', '2009-03-12 23:12:27.000000', NULL, 1),
(5330123, 771734, 18197, '<td valign="top">Wonderful image. Among the best I''ve seen so far. Love the subject, the reflection, the composition and the DOF.</td>', 'Wonderful image. Among the best I''ve seen so far. Love the subject, the reflection, the composition and the DOF.', '2009-03-12 23:12:30.000000', NULL, 1),
(5330125, 772602, 43667, '<td valign="top">Needs better focus and better compression</td>', 'Needs better focus and better compression', '2009-03-12 23:12:43.000000', NULL, 1),
(5330126, 771118, 2615, '<td valign="top">Interesting!</td>', 'Interesting!', '2009-03-12 23:12:52.000000', NULL, 1),
(5330127, 772244, 54228, '<td valign="top">Wonderful looking old place! It''s good to see some character still exists.</td>', 'Wonderful looking old place! It''s good to see some character still exists.', '2009-03-12 23:12:55.000000', NULL, 1),
(5330130, 772289, 77724, '<td valign="top">I have seen the big boy in Green Bay, but it doesn''t run anymore.  Some day I''ll get out west and see this in operation. Splendid capture.</td>', 'I have seen the big boy in Green Bay, but it doesn''t run anymore.  Some day I''ll get out west and see this in operation. Splendid capture.', '2009-03-12 23:13:12.000000', NULL, 1),
(5330131, 771155, 43667, '<td valign="top">Life keeps going? Or the innocence of children?</td>', 'Life keeps going? Or the innocence of children?', '2009-03-12 23:13:12.000000', NULL, 1),
(5330132, 771274, 94235, '<td valign="top">Lighting well used. The hair wisps are are little distracting and cover the excellent skin tones but still a very nice shot.</td>', 'Lighting well used. The hair wisps are are little distracting and cover the excellent skin tones but still a very nice shot.', '2009-03-12 23:13:27.000000', NULL, 1),
(5330134, 770905, 18197, '<td valign="top">They say that, in the cold, all men are created equal ... but they''re speaking anatomically I think. This is nice and makes me believe it''s brutally cold.</td>', 'They say that, in the cold, all men are created equal ... but they''re speaking anatomically I think. This is nice and makes me believe it''s brutally cold.', '2009-03-12 23:13:42.000000', NULL, 1),
(5330135, 770839, 43463, '<td valign="top">Voted earlier coming back to comment now. Nature shows off impressive displays of force and this is just one of them. It must have been even more impressive to see and hear the roar and crash of the waves. Holy cow, those storm waves are extremely high - the inclusion of the lighthouse to the far right gives us a sense of size and scale. Colors show of the hues of a stormy and windblown day with the whites of the frothy waves and the cool steel blue grey sky. Great capture!</td>', 'Voted earlier coming back to comment now. Nature shows off impressive displays of force and this is just one of them. It must have been even more impressive to see and hear the roar and crash of the waves. Holy cow, those storm waves are extremely high - the inclusion of the lighthouse to the far right gives us a sense of size and scale. Colors show of the hues of a stormy and windblown day with the whites of the frothy waves and the cool steel blue grey sky. Great capture!', '2009-03-12 23:13:48.000000', NULL, 1),
(5330136, 771723, 2615, '<td valign="top">Cute! Maybe try black &amp; white or solid background.</td>', 'Cute! Maybe try black & white or solid background.', '2009-03-12 23:13:57.000000', NULL, 1),
(5330137, 772176, 69684, '<td valign="top">Beautiful macro and nice DoF. I like the color tone you used.</td>', 'Beautiful macro and nice DoF. I like the color tone you used.', '2009-03-12 23:14:01.000000', NULL, 1),
(5330138, 772327, 69684, '<td valign="top">Nice eye. I like the desaturation, the brightness and the details. Just puzzling what I see in the reflection.</td>', 'Nice eye. I like the desaturation, the brightness and the details. Just puzzling what I see in the reflection.', '2009-03-12 23:14:05.000000', NULL, 1),
(5330139, 772496, 96751, '<td valign="top">Nice color adjustment.  The pinks and lavenders make a lovely backdrop to a very happy person.  I like that she is just off the ground, and very sharp, under low light conditions.</td>', 'Nice color adjustment.  The pinks and lavenders make a lovely backdrop to a very happy person.  I like that she is just off the ground, and very sharp, under low light conditions.', '2009-03-12 23:14:05.000000', NULL, 1),
(5330140, 772280, 102024, '<td valign="top">Rather disorienting.  I wish the gate were a little more interesting.</td>', 'Rather disorienting.  I wish the gate were a little more interesting.', '2009-03-12 23:14:16.000000', NULL, 1),
(5330141, 771799, 2615, '<td valign="top">Great composition!</td>', 'Great composition!', '2009-03-12 23:14:17.000000', NULL, 1),
(5330142, 772302, 18197, '<td valign="top">It''s an interesting silhouette but on my calibrated moniter it''s hard to tell if there''s more to this.</td>', 'It''s an interesting silhouette but on my calibrated moniter it''s hard to tell if there''s more to this.', '2009-03-12 23:14:27.000000', NULL, 1),
(5330143, 772565, 102024, '<td valign="top">The sky and sea are very painterly, punctuated by the vessel.</td>', 'The sky and sea are very painterly, punctuated by the vessel.', '2009-03-12 23:14:45.000000', NULL, 1),
(5330144, 772284, 2612, '<td valign="top">Ok... I admit to browsing the thumbnails and looking for something to motivate me to vote and comments some more and this is the image that pulled me back. Wonderful light and real emotion. Thanks for sharing.</td>', 'Ok... I admit to browsing the thumbnails and looking for something to motivate me to vote and comments some more and this is the image that pulled me back. Wonderful light and real emotion. Thanks for sharing.', '2009-03-12 23:14:49.000000', NULL, 1),
(5330145, 772377, 96751, '<td valign="top">Did you do it? She looks kind of disappointed...  Very nice portrait.  Very clean lines.  Like the back glow.</td>', 'Did you do it? She looks kind of disappointed...  Very nice portrait.  Very clean lines.  Like the back glow.', '2009-03-12 23:14:58.000000', NULL, 1),
(5330146, 772475, 94235, '<td valign="top">Good solemn shot but looks like the whole picture is sloping to the left a bit.</td>', 'Good solemn shot but looks like the whole picture is sloping to the left a bit.', '2009-03-12 23:15:03.000000', NULL, 1),
(5330147, 771921, 102024, '<td valign="top">Nice capture, but with a tighter crop perhaps it could fit the title better.</td>', 'Nice capture, but with a tighter crop perhaps it could fit the title better.', '2009-03-12 23:15:05.000000', NULL, 1),
(5330148, 771792, 18197, '<td valign="top">Fun subject and capture. I was once seated by a Matre''D who resembled your owl. Thanks for the memory.</td>', 'Fun subject and capture. I was once seated by a Matre''D who resembled your owl. Thanks for the memory.', '2009-03-12 23:15:16.000000', NULL, 1),
(5330149, 771863, 12250, '<td valign="top">Are these DPC''rs?  Great crowd.  What city is this?</td>', 'Are these DPC''rs?  Great crowd.  What city is this?', '2009-03-12 23:15:17.000000', NULL, 1),
(5330151, 772522, 102024, '<td valign="top">Image feels a tad dark.  Nice stopped motion with the water.</td>', 'Image feels a tad dark.  Nice stopped motion with the water.', '2009-03-12 23:15:30.000000', NULL, 1),
(5330152, 772235, 69684, '<td valign="top">Wonderful bright colors! Nice natural division of water and sky.</td>', 'Wonderful bright colors! Nice natural division of water and sky.', '2009-03-12 23:15:32.000000', NULL, 1),
(5330153, 770780, 69684, '<td valign="top">Beautiful view. I like the shape of the boat (and the water inside) and all the green colors.</td>', 'Beautiful view. I like the shape of the boat (and the water inside) and all the green colors.', '2009-03-12 23:15:35.000000', NULL, 1),
(5330154, 772669, 12250, '<td valign="top">Not focused enough but good thought.</td>', 'Not focused enough but good thought.', '2009-03-12 23:15:44.000000', NULL, 1),
(5330155, 770839, 96751, '<td valign="top">I am constantly amazed that these lighthouses can withstand even one of these waves.  Much less years of them!  Amazing capture.  I hope you were in a safe place when you took this...</td>', 'I am constantly amazed that these lighthouses can withstand even one of these waves.  Much less years of them!  Amazing capture.  I hope you were in a safe place when you took this...', '2009-03-12 23:16:02.000000', NULL, 1),
(5330156, 772115, 102024, '<td valign="top">A very nice portrait with a good DOF and well preserved details.  The color conversion is well done too.</td>', 'A very nice portrait with a good DOF and well preserved details.  The color conversion is well done too.', '2009-03-12 23:16:02.000000', NULL, 1),
(5330157, 772104, 18197, '<td valign="top">Superb. Subject(s), composition, even the grain. Among best of show so far!</td>', 'Superb. Subject(s), composition, even the grain. Among best of show so far!', '2009-03-12 23:16:02.000000', NULL, 1),
(5330159, 772636, 94235, '<td valign="top">Fantastic reflection even though the shot looks a little grainy. Well captured.</td>', 'Fantastic reflection even though the shot looks a little grainy. Well captured.', '2009-03-12 23:16:08.000000', NULL, 1),
(5330160, 772602, 2615, '<td valign="top">Good composition but blurry? Can''t tell if it''s focus or depixelation?</td>', 'Good composition but blurry? Can''t tell if it''s focus or depixelation?', '2009-03-12 23:16:14.000000', NULL, 1),
(5330161, 771460, 12250, '<td valign="top">Great colors and DOF.  Nice pic.</td>', 'Great colors and DOF.  Nice pic.', '2009-03-12 23:16:15.000000', NULL, 1),
(5330162, 771190, 18197, '<td valign="top">I love orchids and you made me fall in love with this specific example. Thanks.</td>', 'I love orchids and you made me fall in love with this specific example. Thanks.', '2009-03-12 23:16:29.000000', NULL, 1),
(5330163, 772763, 96751, '<td valign="top">Fun shot.  There is so much to look at, and really bold colors, I almost missed the bodyguard dead center!</td>', 'Fun shot.  There is so much to look at, and really bold colors, I almost missed the bodyguard dead center!', '2009-03-12 23:16:38.000000', NULL, 1),
(5330164, 772397, 12250, '<td valign="top">Good colors and focus.  Nice shot.</td>', 'Good colors and focus.  Nice shot.', '2009-03-12 23:16:46.000000', NULL, 1),
(5330165, 772292, 94235, '<td valign="top">Well processed. The highlight of the path looks great.</td>', 'Well processed. The highlight of the path looks great.', '2009-03-12 23:16:52.000000', NULL, 1),
(5330166, 770241, 2615, '<td valign="top">Great perspective of the falls!</td>', 'Great perspective of the falls!', '2009-03-12 23:17:07.000000', NULL, 1),
(5330167, 772253, 94235, '<td valign="top">Does look a bit bleak.</td>', 'Does look a bit bleak.', '2009-03-12 23:17:08.000000', NULL, 1),
(5330168, 772644, 102024, '<td valign="top">Nice shot but it''s rather cramped in the frame.</td>', 'Nice shot but it''s rather cramped in the frame.', '2009-03-12 23:17:08.000000', NULL, 1),
(5330169, 771378, 18197, '<td valign="top">To be honest I''m tiring of butterflies, but this is among the best of the genre. Good work!</td>', 'To be honest I''m tiring of butterflies, but this is among the best of the genre. Good work!', '2009-03-12 23:17:17.000000', NULL, 1),
(5330170, 772027, 69684, '<td valign="top">Beautiful misty view. I like the soft light.</td>', 'Beautiful misty view. I like the soft light.', '2009-03-12 23:17:20.000000', NULL, 1),
(5330171, 770871, 2612, '<td valign="top">Amazing timing!! I''ve spent hours floating on the water to see nothing more than a little hump slide by in the water.</td>', 'Amazing timing!! I''ve spent hours floating on the water to see nothing more than a little hump slide by in the water.', '2009-03-12 23:17:27.000000', NULL, 1),
(5330172, 771526, 12250, '<td valign="top">Good shot.  The lighting could be a bit softer but still nice.</td>', 'Good shot.  The lighting could be a bit softer but still nice.', '2009-03-12 23:17:33.000000', NULL, 1),
(5330173, 771943, 102024, '<td valign="top">The composition works in some strange way for me.  The subject is rather self explanatory...</td>', 'The composition works in some strange way for me.  The subject is rather self explanatory...', '2009-03-12 23:17:41.000000', NULL, 1),
(5330174, 771190, 12250, '<td valign="top">Nice lighting and color.  Good shot.</td>', 'Nice lighting and color.  Good shot.', '2009-03-12 23:17:57.000000', NULL, 1),
(5330175, 770933, 18197, '<td valign="top">I wouldn''t mind standing where you are and soaking up the vista. Thanks for showing us this pretty place.</td>', 'I wouldn''t mind standing where you are and soaking up the vista. Thanks for showing us this pretty place.', '2009-03-12 23:18:00.000000', NULL, 1),
