(5330395, 772710, 67579, '<td valign="top">wonderful portrait, great use and balance of warm and cold lighting.</td>', 'wonderful portrait, great use and balance of warm and cold lighting.', '2009-03-12 23:45:33.000000', NULL, 1),
(5330396, 771434, 71244, '<td valign="top">stunning. no vote, but stunning.</td>', 'stunning. no vote, but stunning.', '2009-03-12 23:45:40.000000', NULL, 1),
