(5330577, 772590, 18197, '<td valign="top">Very well executed photo of a subject that lets me down a bit.</td>', 'Very well executed photo of a subject that lets me down a bit.', '2009-03-13 00:02:10.000000', NULL, 1),
(5330580, 771156, 2389, '<td valign="top">what a macro - i like the colors and the contrasts...</td>', 'what a macro - i like the colors and the contrasts...', '2009-03-13 00:02:25.000000', NULL, 1),
(5330581, 770317, 69684, '<td valign="top">Impressive sky. Nice to see some dimension with the cars on the road.</td>', 'Impressive sky. Nice to see some dimension with the cars on the road.', '2009-03-13 00:02:28.000000', NULL, 1),
