INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5331778, 771244, 30364, '<td valign="top">There''s a lovely 1960s quality about this, as if Helena is a movie star of that era who turned out to be far too good and complex for the movie industry''s subsequent slide into superficiality and banality.  A very fine portrait.  7.</td>', 'There''s a lovely 1960s quality about this, as if Helena is a movie star of that era who turned out to be far too good and complex for the movie industry''s subsequent slide into superficiality and banality.  A very fine portrait.  7.', '2009-03-13 03:28:54.000000', NULL, 1),
(5331779, 772338, 102024, '<td valign="top">Lovely colors in a simple and effective composition and good DOF.</td>', 'Lovely colors in a simple and effective composition and good DOF.', '2009-03-13 03:30:26.000000', NULL, 1),
