(5345106, 770644, 69684, '<td valign="top">Beautiful view of the village and the abbey. The postprocessing gives this a dramatic feeling.</td>', 'Beautiful view of the village and the abbey. The postprocessing gives this a dramatic feeling.', '2009-03-14 03:07:42.000000', NULL, 1),
(5345107, 772634, 31664, '<td valign="top">I really like the 2D silhouette look to this.</td>', 'I really like the 2D silhouette look to this.', '2009-03-14 03:08:13.000000', NULL, 1),
(5345108, 771797, 31664, '<td valign="top">Like the humor :)</td>', 'Like the humor :)', '2009-03-14 03:08:39.000000', NULL, 1),
(5345109, 772457, 92643, '<td valign="top">Great find, but I feel like the camera''s focus is off and the fascinating broken machinery is too hard to distinguish due to its darkness and the many cluttering elements.</td>', 'Great find, but I feel like the camera''s focus is off and the fascinating broken machinery is too hard to distinguish due to its darkness and the many cluttering elements.', '2009-03-14 03:08:40.000000', NULL, 1),
