INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5347896, 770976, 84438, '<td valign="top">Very nice black and white conversion.  Nice emotive shot.</td>', 'Very nice black and white conversion.  Nice emotive shot.', '2009-03-14 10:48:23.000000', NULL, 1),
(5347898, 772622, 15305, '<td valign="top">Nice pup, good composition. The lighting hurts it a bit.</td>', 'Nice pup, good composition. The lighting hurts it a bit.', '2009-03-14 10:48:38.000000', NULL, 1),
(5347899, 772738, 103142, '<td valign="top">I''m sorry, the light seems way too heavy and the close shadow doesn''t add anything IMO. I''d soften the light and move her away from the background. The angle also makes her arm look very heavy.</td>', 'I''m sorry, the light seems way too heavy and the close shadow doesn''t add anything IMO. I''d soften the light and move her away from the background. The angle also makes her arm look very heavy.', '2009-03-14 10:49:00.000000', NULL, 1),
(5347900, 772281, 81530, '<td valign="top">Very nice colours and blurred background. It''s difficult to find the focus on her face.</td>', 'Very nice colours and blurred background. It''s difficult to find the focus on her face.', '2009-03-14 10:49:08.000000', NULL, 1),
(5347901, 770570, 84438, '<td valign="top">Beautiful.  What a location, and very nicely taken.</td>', 'Beautiful.  What a location, and very nicely taken.', '2009-03-14 10:49:14.000000', NULL, 1),
(5347902, 772472, 67258, '<td valign="top">The classic tern shot - and perfectly done.  Bumping to 9.</td>', 'The classic tern shot - and perfectly done.  Bumping to 9.', '2009-03-14 10:49:14.000000', NULL, 1),
(5347903, 772720, 98339, '<td valign="top">I liked the processing on your last entry better...what I liked better were the "rich tones"...I will be curious as to what the differences are in the PP notes...his eyes are so compelling they draw you in...excellent shot, it holds your attention</td>', 'I liked the processing on your last entry better...what I liked better were the "rich tones"...I will be curious as to what the differences are in the PP notes...his eyes are so compelling they draw you in...excellent shot, it holds your attention', '2009-03-14 10:49:22.000000', NULL, 1),
(5347904, 772691, 79141, '<td valign="top">ohhhhhhhh way to light not a lot of contrast</td>', 'ohhhhhhhh way to light not a lot of contrast', '2009-03-14 10:49:28.000000', NULL, 1),
(5347905, 771955, 81530, '<td valign="top">It''s almost impossible these days to photograph the falls without getting all the mist in the way.</td>', 'It''s almost impossible these days to photograph the falls without getting all the mist in the way.', '2009-03-14 10:49:33.000000', NULL, 1),
(5347906, 770810, 81530, '<td valign="top">Looks like he caught his lunch.</td>', 'Looks like he caught his lunch.', '2009-03-14 10:49:46.000000', NULL, 1),
