(5347915, 771581, 79141, '<td valign="top">wonderful tones  and  so sharp good detail</td>', 'wonderful tones  and  so sharp good detail', '2009-03-14 10:50:50.000000', NULL, 1),
(5347916, 770485, 81530, '<td valign="top">Good composition. I like how the waves distort the reflection of the treeline.</td>', 'Good composition. I like how the waves distort the reflection of the treeline.', '2009-03-14 10:50:59.000000', NULL, 1),
(5347917, 772591, 84438, '<td valign="top">WOW.  Incredible location..  Beautiful, just beautiful!</td>', 'WOW.  Incredible location..  Beautiful, just beautiful!', '2009-03-14 10:51:07.000000', NULL, 1),
(5347918, 771657, 76335, '<td valign="top">Too bad DPC doesn''t give us the tools to better show off panoramas. This is a good one.</td>', 'Too bad DPC doesn''t give us the tools to better show off panoramas. This is a good one.', '2009-03-14 10:51:13.000000', NULL, 1),
