INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5348669, 771673, 77196, '<td valign="top">Love the stark white of the Jefferson Memorial. Nice winter scene.</td>', 'Love the stark white of the Jefferson Memorial. Nice winter scene.', '2009-03-14 11:54:49.000000', NULL, 1),
(5348670, 772054, 43463, '<td valign="top">Voted earlier coming back to leave comments. Wow, you did a spectacular job in the processing. The contrast in the hues of the wood of this chapel really pop visually and carry the weight of this church weathering decades of time, wind and rain. The thing that really contrast most with the time weathered wood is that bold red door. To me it carries off the idea that although this chapel may be old there is plenty of vibrancy and life left here. The red also jumps out at me as a symbolic color of love - and since this is a place where two souls are joined in marriage, it is a perfect color for a door that will open to a new path were two are joined as one in a partnership. The colors throughout this photo are bold and vibrant which also catches and holds the eye. The architecture of the church with arches and shape also holds the eye''s attention.</td>', 'Voted earlier coming back to leave comments. Wow, you did a spectacular job in the processing. The contrast in the hues of the wood of this chapel really pop visually and carry the weight of this church weathering decades of time, wind and rain. The thing that really contrast most with the time weathered wood is that bold red door. To me it carries off the idea that although this chapel may be old there is plenty of vibrancy and life left here. The red also jumps out at me as a symbolic color of love - and since this is a place where two souls are joined in marriage, it is a perfect color for a door that will open to a new path were two are joined as one in a partnership. The colors throughout this photo are bold and vibrant which also catches and holds the eye. The architecture of the church with arches and shape also holds the eye''s attention.', '2009-03-14 11:54:54.000000', NULL, 1),
(5348672, 772575, 95579, '<td valign="top">great colours &amp; curves</td>', 'great colours & curves', '2009-03-14 11:55:02.000000', NULL, 1),
