(5350119, 772191, 11854, '<td valign="top">Coming back to comment...<br/> <br/>Gorgeous, wonderful drop reflections! So abstract, love it! 10</td>', 'Coming back to comment... Gorgeous, wonderful drop reflections! So abstract, love it! 10', '2009-03-14 14:47:56.000000', NULL, 1),
(5350121, 772612, 33732, '<td valign="top">Look at that sparkle. Nice.</td>', 'Look at that sparkle. Nice.', '2009-03-14 14:48:31.000000', NULL, 1),
(5350122, 772354, 83313, '<td valign="top">A little grainy from what looks like a severe crop, but you have most of the bee in focus, which is something I have found challenging with photographing bugs.</td>', 'A little grainy from what looks like a severe crop, but you have most of the bee in focus, which is something I have found challenging with photographing bugs.', '2009-03-14 14:48:34.000000', NULL, 1),
