(5353249, 771952, 68467, '<td valign="top">strange but great macro - like the bw stile</td>', 'strange but great macro - like the bw stile', '2009-03-14 19:49:07.000000', NULL, 1),
(5353250, 772178, 77196, '<td valign="top">No Left Turn allowed! Nice lighting. Reminds me of rock-hunting with a friend when I was in Jr. High - we were up above the clouds, and whole valleys were filled with clouds, but it was sunny where we were - right through sunset, and then we had to come back.</td>', 'No Left Turn allowed! Nice lighting. Reminds me of rock-hunting with a friend when I was in Jr. High - we were up above the clouds, and whole valleys were filled with clouds, but it was sunny where we were - right through sunset, and then we had to come back.', '2009-03-14 19:49:11.000000', NULL, 1),
(5353251, 770380, 33732, '<td valign="top">Color and shadows are nice.</td>', 'Color and shadows are nice.', '2009-03-14 19:49:17.000000', NULL, 1);
