(5353253, 772058, 94235, '<td valign="top">Well framed. Great tones and clarity.</td>', 'Well framed. Great tones and clarity.', '2009-03-14 19:49:35.000000', NULL, 1),
(5353255, 771737, 77196, '<td valign="top">Great title and great shot. Nice textures in icicles, snow and water falls. Nice use of a slightly blue tone to increase the feeling of cole.</td>', 'Great title and great shot. Nice textures in icicles, snow and water falls. Nice use of a slightly blue tone to increase the feeling of cole.', '2009-03-14 19:49:48.000000', NULL, 1),
