(5353257, 772492, 33732, '<td valign="top">Cute but contrast is a issue.</td>', 'Cute but contrast is a issue.', '2009-03-14 19:49:52.000000', NULL, 1),
(5353258, 772480, 76335, '<td valign="top">I kno who this is. I like this a lot. Anything with a strong geometric grounding is a winner by me. There are a few other things I like about this though, namely the human element and the low-key, greenish processing. A winner by me. 1x''s loss for not accepting it.</td>', 'I kno who this is. I like this a lot. Anything with a strong geometric grounding is a winner by me. There are a few other things I like about this though, namely the human element and the low-key, greenish processing. A winner by me. 1x''s loss for not accepting it.', '2009-03-14 19:49:57.000000', NULL, 1),
(5353260, 771322, 2615, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-03-14 19:49:58.000000', NULL, 1),
