(5356106, 772592, 77196, '<td valign="top">Great motion shot.</td>', 'Great motion shot.', '2009-03-14 23:30:22.000000', NULL, 1),
(5356107, 772634, 47541, '<td valign="top">I like the fog vs silhouette concept</td>', 'I like the fog vs silhouette concept', '2009-03-14 23:30:42.000000', NULL, 1),
