(5362505, 770386, 9411, '<td valign="top">Lovely image, just enough dof to give an air of mystery</td>', 'Lovely image, just enough dof to give an air of mystery', '2009-03-15 11:59:39.000000', NULL, 1),
(5362506, 770921, 43774, '<td valign="top">I like the composition. I wish the bee were in focus though.</td>', 'I like the composition. I wish the bee were in focus though.', '2009-03-15 11:59:39.000000', NULL, 1),
(5362507, 772588, 43774, '<td valign="top">A nice bright photo, good composition.</td>', 'A nice bright photo, good composition.', '2009-03-15 11:59:41.000000', NULL, 1),
(5362508, 771687, 9411, '<td valign="top">Really fine image. soft detail and a little mystery</td>', 'Really fine image. soft detail and a little mystery', '2009-03-15 11:59:41.000000', NULL, 1),
(5362509, 771228, 43774, '<td valign="top">My favourite part of this photo is the boat on the left. The photo seems too contrasty for my tastes.</td>', 'My favourite part of this photo is the boat on the left. The photo seems too contrasty for my tastes.', '2009-03-15 11:59:43.000000', NULL, 1),
(5362510, 770969, 9411, '<td valign="top">Love the light,</td>', 'Love the light,', '2009-03-15 11:59:45.000000', NULL, 1),
(5362511, 771035, 43774, '<td valign="top">Is this in Disney World? My brother just got back from there and he had a picture of a woman dressed up like a tree/vines.<br/> <br/>This looks a bit fuzzy and pixelated.</td>', 'Is this in Disney World? My brother just got back from there and he had a picture of a woman dressed up like a tree/vines. This looks a bit fuzzy and pixelated.', '2009-03-15 11:59:45.000000', NULL, 1),
