(5370040, 772381, 15305, '<td valign="top">Excellent color and detail.</td>', 'Excellent color and detail.', '2009-03-16 00:07:37.000000', NULL, 1),
(5370043, 772535, 37845, '<td valign="top">Nice portrait. She has a beautiful smile.</td>', 'Nice portrait. She has a beautiful smile.', '2009-03-16 00:07:57.000000', NULL, 1),
(5370044, 771290, 15305, '<td valign="top">Wonderful capture, excellent sharpness and detail.</td>', 'Wonderful capture, excellent sharpness and detail.', '2009-03-16 00:08:02.000000', NULL, 1),
