(5379087, 771975, 77196, '<td valign="top">Love the red rocks and natural arch, with scattered spots of green here and there.</td>', 'Love the red rocks and natural arch, with scattered spots of green here and there.', '2009-03-16 23:36:45.000000', NULL, 1),
(5379088, 770930, 9668, '<td valign="top">cool to include the people - artistically blurry, the and the fireworks. would like to see a better composition of this though. perhaps vertical?</td>', 'cool to include the people - artistically blurry, the and the fireworks. would like to see a better composition of this though. perhaps vertical?', '2009-03-16 23:36:48.000000', NULL, 1),
