(5379200, 770752, 31637, '<td valign="top">This is magical, complete masterpiece, artistically and technically! 10</td>', 'This is magical, complete masterpiece, artistically and technically! 10', '2009-03-16 23:52:33.000000', NULL, 1),
(5379201, 772130, 77196, '<td valign="top">Interesting head dress, bangles, and "glove".</td>', 'Interesting head dress, bangles, and "glove".', '2009-03-16 23:52:50.000000', NULL, 1),
