(5384245, 772570, 91197, '<td valign="top">Nice scene. Not very interesting though.</td>', 'Nice scene. Not very interesting though.', '2009-03-17 15:28:20.000000', NULL, 1),
(5384246, 770314, 99263, '<td valign="top">Beautiful golden leave dappled rocks.</td>', 'Beautiful golden leave dappled rocks.', '2009-03-17 15:28:34.000000', NULL, 1),
(5384248, 772547, 91197, '<td valign="top">It s heading to me!</td>', 'It s heading to me!', '2009-03-17 15:28:56.000000', NULL, 1),
(5384250, 771892, 91197, '<td valign="top">So sweet.</td>', 'So sweet.', '2009-03-17 15:29:29.000000', NULL, 1),
(5384252, 772368, 98141, '<td valign="top">Great colors, the focus seems a little soft, I love the bokeh and the green there.</td>', 'Great colors, the focus seems a little soft, I love the bokeh and the green there.', '2009-03-17 15:29:48.000000', NULL, 1),
(5384253, 771717, 99263, '<td valign="top">Nice processing with lovely textures. I like the red flowers interspersing the grey''s and breaking the monotony.</td>', 'Nice processing with lovely textures. I like the red flowers interspersing the grey''s and breaking the monotony.', '2009-03-17 15:29:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5384254, 771266, 98141, '<td valign="top">Great action shot, I love the golden hues here.</td>', 'Great action shot, I love the golden hues here.', '2009-03-17 15:30:07.000000', NULL, 1),
(5384256, 770219, 99263, '<td valign="top">Very nice evening street shot.</td>', 'Very nice evening street shot.', '2009-03-17 15:30:19.000000', NULL, 1),
(5384258, 771807, 71239, '<td valign="top">Cute baby - I might have cropped in a bit tighter on both sides and not have gone for the blur effect - I think the baby and the bucket would make the shot without it.</td>', 'Cute baby - I might have cropped in a bit tighter on both sides and not have gone for the blur effect - I think the baby and the bucket would make the shot without it.', '2009-03-17 15:30:27.000000', NULL, 1),
(5384259, 772168, 63499, '<td valign="top">I like how the color, lighting and textures flow across the photo. Everything seems woven in with another part of the image and my eye keeps moving from one thing to the next trying to take it all in. It''s a beautiful view!</td>', 'I like how the color, lighting and textures flow across the photo. Everything seems woven in with another part of the image and my eye keeps moving from one thing to the next trying to take it all in. It''s a beautiful view!', '2009-03-17 15:30:29.000000', NULL, 1),
(5384260, 772578, 52549, '<td valign="top">Fabulous image, MAK. Love it to bits. Hope it does well for you.</td>', 'Fabulous image, MAK. Love it to bits. Hope it does well for you.', '2009-03-17 15:30:39.000000', NULL, 1),
(5384261, 770771, 98141, '<td valign="top">This is a wonderful portrait, really has character, fantastic lighting, I just love this.</td>', 'This is a wonderful portrait, really has character, fantastic lighting, I just love this.', '2009-03-17 15:30:42.000000', NULL, 1),
(5384262, 770255, 30861, '<td valign="top">IN many ways this is utterly fascinating; I find myself studying each of the "characters" for clues as to their identity/business/state of mind. It bothers me that the prominent wall junction is not squared up a little better, easy enough to do with a little skew tool. But the deal-breaker, for me, is that the image seems seriously oversharpened, and I''m picking up fine halo-type outlining of the figures against the neutral walls. That''s holding it back from climbing into the 8''s, and it will stay at 7 in my scoring.<br/> <br/>Nevertheless, well seen and a pleasure to contemplate.</td>', 'IN many ways this is utterly fascinating; I find myself studying each of the "characters" for clues as to their identity/business/state of mind. It bothers me that the prominent wall junction is not squared up a little better, easy enough to do with a little skew tool. But the deal-breaker, for me, is that the image seems seriously oversharpened, and I''m picking up fine halo-type outlining of the figures against the neutral walls. That''s holding it back from climbing into the 8''s, and it will stay at 7 in my scoring. Nevertheless, well seen and a pleasure to contemplate.', '2009-03-17 15:30:51.000000', NULL, 1),
(5384263, 772769, 40490, '<td valign="top">Curious depth of field on this image. I would recommend increasing the D.O.F just slightly to get both the pistol and stamens in sharper focus</td>', 'Curious depth of field on this image. I would recommend increasing the D.O.F just slightly to get both the pistol and stamens in sharper focus', '2009-03-17 15:30:53.000000', NULL, 1),
(5384265, 772750, 98141, '<td valign="top">I like the composition, the focus seems a little soft but this makes me happy, it feels so carefree.</td>', 'I like the composition, the focus seems a little soft but this makes me happy, it feels so carefree.', '2009-03-17 15:31:07.000000', NULL, 1),
(5384269, 772272, 98141, '<td valign="top">I like the subtle pattern on the surface behind the hand, it ties in very nicely.</td>', 'I like the subtle pattern on the surface behind the hand, it ties in very nicely.', '2009-03-17 15:31:26.000000', NULL, 1),
(5384271, 772202, 99263, '<td valign="top">Nice composition with lovely raw textures and contrasts. Excellent sepia conversion. 7</td>', 'Nice composition with lovely raw textures and contrasts. Excellent sepia conversion. 7', '2009-03-17 15:31:34.000000', NULL, 1),
(5384273, 771563, 98141, '<td valign="top">Great, colorful shot of architecture in a reflection.</td>', 'Great, colorful shot of architecture in a reflection.', '2009-03-17 15:31:39.000000', NULL, 1),
(5384275, 770341, 99263, '<td valign="top">Creative image, well seen.</td>', 'Creative image, well seen.', '2009-03-17 15:31:48.000000', NULL, 1),
(5384279, 772176, 99263, '<td valign="top">Very nice and interesting close-up</td>', 'Very nice and interesting close-up', '2009-03-17 15:31:55.000000', NULL, 1),
(5384280, 771348, 99263, '<td valign="top">Nice old red firetruck. Lovely setting.</td>', 'Nice old red firetruck. Lovely setting.', '2009-03-17 15:31:57.000000', NULL, 1),
(5384283, 771734, 30861, '<td valign="top">Love the way the owl is "floating" there, and of course am just utterly bemused by the incongruity of an owl on a railroad track :-) Almost wish you''d titled it "My Trained Owl" :-) 7 from me.</td>', 'Love the way the owl is "floating" there, and of course am just utterly bemused by the incongruity of an owl on a railroad track :-) Almost wish you''d titled it "My Trained Owl" :-) 7 from me.', '2009-03-17 15:32:05.000000', NULL, 1),
(5384284, 770783, 98141, '<td valign="top">Wow, that is one intense waterfall, I think you did a great job with the exposure, the water doesn''t seem too smooth or solid.</td>', 'Wow, that is one intense waterfall, I think you did a great job with the exposure, the water doesn''t seem too smooth or solid.', '2009-03-17 15:32:09.000000', NULL, 1),
(5384286, 772592, 91197, '<td valign="top">I am not sure about the post proccesing here it looks unatural to me.</td>', 'I am not sure about the post proccesing here it looks unatural to me.', '2009-03-17 15:32:12.000000', NULL, 1),
(5384300, 772304, 71239, '<td valign="top">Interesting old building and nice ground colours, it''s a pity the sky was so grey.  Maybe dropping the viewpoint down a bit and moving in closer would have given more of the building and foreground whilst reducing the amount of sky in shot?</td>', 'Interesting old building and nice ground colours, it''s a pity the sky was so grey.  Maybe dropping the viewpoint down a bit and moving in closer would have given more of the building and foreground whilst reducing the amount of sky in shot?', '2009-03-17 15:32:57.000000', NULL, 1),
(5384306, 772718, 40490, '<td valign="top">Very sharp and clean. Nice expression, well placed entities</td>', 'Very sharp and clean. Nice expression, well placed entities', '2009-03-17 15:33:04.000000', NULL, 1),
(5384310, 771975, 98141, '<td valign="top">Great natural architecture, wonderful capture of stunning landscape.</td>', 'Great natural architecture, wonderful capture of stunning landscape.', '2009-03-17 15:33:25.000000', NULL, 1),
(5384312, 772103, 98141, '<td valign="top">I love the composition in this, the yellows and the blues are great together.</td>', 'I love the composition in this, the yellows and the blues are great together.', '2009-03-17 15:33:38.000000', NULL, 1),
(5384313, 771694, 30861, '<td valign="top">I got a love/hate thing going on this image. At many levels it''s stunning, but the colors seem seriously "off" to me. I imagine they''re what you *wanted*, but it just seems to ocherey (I know that ain''t a word) to my eye. Still, extraordinary capture, well seen, and a 7 from me.</td>', 'I got a love/hate thing going on this image. At many levels it''s stunning, but the colors seem seriously "off" to me. I imagine they''re what you *wanted*, but it just seems to ocherey (I know that ain''t a word) to my eye. Still, extraordinary capture, well seen, and a 7 from me.', '2009-03-17 15:33:43.000000', NULL, 1),
(5384314, 770153, 98141, '<td valign="top">I love the exposure on this, her hair and makeup are so subtle yet they pop. Classic.</td>', 'I love the exposure on this, her hair and makeup are so subtle yet they pop. Classic.', '2009-03-17 15:34:04.000000', NULL, 1),
(5384315, 770216, 71239, '<td valign="top">Nice pet portrait, I like the way the light neck hair forms a soft background to the face.</td>', 'Nice pet portrait, I like the way the light neck hair forms a soft background to the face.', '2009-03-17 15:34:05.000000', NULL, 1),
(5384316, 772098, 98141, '<td valign="top">Haha, great capture, I''m sure that took a lot of takes! They look like they''re having a blast.</td>', 'Haha, great capture, I''m sure that took a lot of takes! They look like they''re having a blast.', '2009-03-17 15:34:23.000000', NULL, 1),
(5384317, 771526, 91197, '<td valign="top">Dont really get a feeling out of this one. I think she looks at me and I dont know why...</td>', 'Dont really get a feeling out of this one. I think she looks at me and I dont know why...', '2009-03-17 15:34:38.000000', NULL, 1),
