(5387374, 771534, 70270, '<td valign="top">The hand of Monet on your shoulder.  Very nice.</td>', 'The hand of Monet on your shoulder.  Very nice.', '2009-03-17 22:09:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5387375, 772637, 82999, '<td valign="top">I was sooooo tempted to shoot some frozen lake pictures this year and I didn''t.  You''ve really made me regret it.  Excellent.</td>', 'I was sooooo tempted to shoot some frozen lake pictures this year and I didn''t.  You''ve really made me regret it.  Excellent.', '2009-03-17 22:09:30.000000', NULL, 1),
(5387378, 772407, 70270, '<td valign="top">toooooo funny</td>', 'toooooo funny', '2009-03-17 22:09:50.000000', NULL, 1),
(5387379, 770631, 80096, '<td valign="top">Great sense of design, lights and darks! 7</td>', 'Great sense of design, lights and darks! 7', '2009-03-17 22:09:51.000000', NULL, 1),
(5387381, 772724, 77196, '<td valign="top">Nice fish-eye of the cathedral. Beautiful color and lines.</td>', 'Nice fish-eye of the cathedral. Beautiful color and lines.', '2009-03-17 22:09:54.000000', NULL, 1),
(5387382, 771981, 77196, '<td valign="top">Great shot. The placement of the manor, offset by the tree, with wonderful clouds floating by.</td>', 'Great shot. The placement of the manor, offset by the tree, with wonderful clouds floating by.', '2009-03-17 22:10:03.000000', NULL, 1),
