(5387403, 772418, 77196, '<td valign="top">Looks like an oversized bedroom to me. Nice contrast of material, bed, and nature browns.</td>', 'Looks like an oversized bedroom to me. Nice contrast of material, bed, and nature browns.', '2009-03-17 22:11:24.000000', NULL, 1),
(5387404, 771822, 82999, '<td valign="top">For me, the absolute best portrait in this challenge, hands down.  I have nothing critical to offer.  Couldn''t be better IHMO.</td>', 'For me, the absolute best portrait in this challenge, hands down.  I have nothing critical to offer.  Couldn''t be better IHMO.', '2009-03-17 22:11:27.000000', NULL, 1),
(5387405, 772533, 70484, '<td valign="top">I love the border effect here!! Your model is great, it seems like she is a little sassy. It photographs well!</td>', 'I love the border effect here!! Your model is great, it seems like she is a little sassy. It photographs well!', '2009-03-17 22:11:28.000000', NULL, 1),
